package com.bank.note;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PaymentNoteDemo {
    private static final Logger log = Logger.getLogger(PaymentNoteDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        // A payment note containing a money-bag emoji (U+1F4B0, supplementary).
        String emoji = new String(Character.toChars(0x1F4B0)); // one visible char, two code units
        String note = "Gift " + emoji + " for Priya";

        PaymentNoteService svc = new PaymentNoteService();

        // Naive length counts code units (emoji counts as 2) vs real characters.
        log.warning(() -> "note.length() code units = " + note.length());
        log.info(() -> "real character count = " + svc.charCount(note));

        // Surrogate inspection of the emoji.
        svc.inspectSurrogates(emoji);

        // Safe truncation on code-point boundaries (never splits the emoji).
        String truncated = svc.safeTruncate(note, 7);
        log.info(() -> "safe truncate to 7 chars = '" + truncated + "'");

        log.info(() -> "Transfer note stored for " + rajesh.getAccountId()
                + " -> " + priya.getAccountId());
    }
}

