class PaymentNoteService {
    private static final Logger log = Logger.getLogger(PaymentNoteService.class.getName());

    // Real character count = code points, not UTF-16 code units.
    int charCount(String s) {
        return s.codePointCount(0, s.length());
    }

    // Truncate to N code points so a surrogate pair is never split.
    String safeTruncate(String s, int maxCodePoints) {
        if (s.codePointCount(0, s.length()) <= maxCodePoints) return s;
        int end = s.offsetByCodePoints(0, maxCodePoints); // index at a safe boundary
        return s.substring(0, end);
    }

    // Show how one supplementary char decomposes into a surrogate pair.
    void inspectSurrogates(String oneEmoji) {
        char high = oneEmoji.charAt(0);
        char low  = oneEmoji.charAt(1);
        log.fine(() -> "isHighSurrogate(high) = " + Character.isHighSurrogate(high));
        log.fine(() -> "isLowSurrogate(low)   = " + Character.isLowSurrogate(low));
        int codePoint = Character.toCodePoint(high, low);
        log.info(() -> "recombined code point = U+"
                + Integer.toHexString(codePoint).toUpperCase()
                + " (via codePointAt = U+"
                + Integer.toHexString(oneEmoji.codePointAt(0)).toUpperCase() + ")");
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
